on conflict (id) do nothing;

on conflict (id) do update set name = excluded.name, region = excluded.region, creature_id = excluded.creature_id, spawns = excluded.spawns, rect = excluded.rect, door = excluded.door, level_min = excluded.level_min,
  zone = excluded.zone, wregion = excluded.wregion, tier = excluded.tier, city_id = excluded.city_id, ring = excluded.ring;


